    $db->exec("INSERT INTO clubs VALUES('own-invoicebank-recovery','Own invoice bank recovery');INSERT INTO actors(id,club_id,role,is_superuser)VALUES('own-invoicebank-recovery-admin','own-invoicebank-recovery','members',1)");
    $settings=new \Kulturhus\Verein\Settings($db,$actor);$finance=new \Kulturhus\Verein\Finance($db,$actor);$requests=new \Kulturhus\Verein\Settings\GeneralRequests($db,$actor);
