    $invoice=(new \Kulturhus\Verein\ContributionInvoices($db,$actor))->issue($entryId);if($invoice['state']!=='issued')throw new RuntimeException('Actual earlier issued invoice required.');
    $file=(new \Kulturhus\Verein\Documents($db,$actor))->file($invoice['document_id']);$snapshot=\Kulturhus\Native\Shared\Db::run($db,'SELECT snapshot FROM document_files WHERE club_id=? AND document_id=? AND revision=1',[$club,$invoice['document_id']])->fetchColumn();
    $pdf=['name'=>$file['name'],'mime'=>$file['mime'],'sha256'=>hash('sha256',$file['bytes']),'snapshot'=>$snapshot];$entry=$finance->entry($entryId);$positions=$finance->positions('entry',$entryId);
    $input=\Kulturhus\Verein\Settings\FinanceBankInput::initial($settings->section('bank'));$input['data']=array_replace($input['data'],['account_id'=>$other,'holder'=>str_repeat('ö',180),'iban'=>'de89 3704 0044 0532 0130 00','bic'=>'cobadeffxxx','paypal'=>'https://example.invalid/own-bank-0']);
    $review=$requests->prepare('bank',$input);$first=$requests->accept('bank',$input,bin2hex(random_bytes(16)),$review['hash'],true);
    $input=\Kulturhus\Verein\Settings\FinanceBankInput::initial($settings->section('bank'));$input['data']=array_replace($input['data'],['account_id'=>$account,'holder'=>'0','iban'=>'DE12500105170648489890','bic'=>'INGDDEFFXXX']);
    $review=$requests->prepare('bank',$input);$later=$requests->accept('bank',$input,bin2hex(random_bytes(16)),$review['hash'],true);
    $finance->saveAccountSettings($account,0,false,'',true,false,'Own later inactive original invoice account');
    $db->beginTransaction();try{$currentSource=\Kulturhus\Verein\Settings\FinanceBankContext::read($db,$actor,$settings->section('bank')['data']);}finally{$db->rollBack();}
    return compact('first','later','raw','entry','positions','invoice','pdf','currentSource','oldBank')+['current'=>$settings->section('bank')];
}
